import TermTable from "@/components/TermTable";
import { getCodebookHtml, getLexicon } from "@/lib/data";

export const metadata = { title: "Codebook · California DV Law Index" };

export default function CodebookPage() {
  // codebook.html is generated by dv_index/update.py from CODEBOOK.md (our own file).
  const html = getCodebookHtml().replace(/<table>/g, '<div class="table-wrap"><table>').replace(/<\/table>/g, "</table></div>");
  return (
    <div className="panel">
      <article className="prose" dangerouslySetInnerHTML={{ __html: html }} />
      <TermTable terms={getLexicon()} />
    </div>
  );
}
